input.command:
cd /Users/guygouri/Devlab/ernlang/ern/formal; python3 -I - <<'EOF'
import re
for f, ident in [("Ern/Lib/HandlePool.lean","HandlePool v0.5"),("Ern/Lib/DataStack.lean","DS-v2")]:
    src=open(f).read()
    # find docstrings followed by a declaration
    pat=re.compile(r'/--(.*?)-/\s*\n\s*((?:private\s+)?(?:theorem|def|structure|inductive|instance|abbrev))\s+([^\s(:{\[]*)', re.S)
    n=0; miss_id=[]; miss_sec=[]; miss_nn=0
    for m in pat.finditer(src):
        n+=1
        doc=m.group(1); name=m.group(3)
        line=src[:m.start()].count('\n')+1
        if ident not in doc: miss_id.append((line,m.group(2),name))
        if '§' not in doc: miss_sec.append((line,m.group(2),name))
        if 'non-normative' not in doc: miss_nn+=1
    print(f, "docstrings:",n,"missing identifier:",len(miss_id),"missing §:",len(miss_sec),"missing 'non-normative':",miss_nn)
    for x in miss_id: print("  noid",x)
    for x in miss_sec: print("  nosec",x)
    # declarations without any docstring
    decl=re.compile(r'^(theorem|def|structure|inductive|instance|abbrev)\s', re.M)
    for d in decl.finditer(src):
        before=src[:d.start()].rstrip()
        if not before.endswith('-/'):
            print("  nodoc line", src[:d.start()].count('\n')+1, src[d.start():d.start()+60].splitlines()[0])
EOF

